"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface ScissorsIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface ScissorsIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const ScissorsIcon = forwardRef<ScissorsIconHandle, ScissorsIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const bladeVariants: Variants = {
   normal: { rotate: 0 },
   animate: (dir: number) => ({
    rotate: [0, 16 * dir, 0, 16 * dir, 0],
    transition: { duration: 0.7 * duration, ease: "easeInOut" },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.g
       variants={bladeVariants}
       custom={-1}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      >
       <circle cx="6" cy="6" r="3" />
       <path d="M8.12 8.12 12 12" />
       <path d="M14.8 14.8 20 20" />
      </m.g>
      <m.g
       variants={bladeVariants}
       custom={1}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      >
       <path d="M20 4 8.12 15.88" />
       <circle cx="6" cy="18" r="3" />
      </m.g>
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

ScissorsIcon.displayName = "ScissorsIcon";
export { ScissorsIcon };
